INSERT INTO is_dua_categories (slug, name, icon, sort_order) VALUES ('quran', '{"en": "Duas from the Quran", "bn": "কুরআনের দোয়া", "ar": "أدعية من القرآن"}', 'book-open', 0) ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('d985bf45-e046-5ae0-b1d4-0149d4621546', '{"en": "Ayat al-Kursi", "bn": "আয়াতুল কুরসি"}', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌۭ وَلَا نَوْمٌۭ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍۢ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', '{"en": "Allahu la ilaha illa huwal-hayyul-qayyum…", "bn": "আল্লাহু লা ইলাহা ইল্লা হুওয়াল হাইয়ুল কাইয়ুম…"}', '{"en": "Allah — there is no god but Him, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and the earth. Who could intercede with Him except by His permission? He knows what is before them and what is behind them, and they encompass nothing of His knowledge except what He wills. His Throne extends over the heavens and the earth, and guarding them does not tire Him. He is the Most High, the Most Great.", "bn": "আল্লাহ, তিনি ছাড়া কোনো উপাস্য নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তন্দ্রা বা ঘুম তাঁকে স্পর্শ করে না। আসমান ও জমিনে যা কিছু আছে সব তাঁরই। তাঁর অনুমতি ছাড়া কে তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পেছনে যা আছে তিনি জানেন; তিনি যা চান তা ছাড়া তাঁর জ্ঞানের কিছুই তারা আয়ত্ত করতে পারে না। তাঁর কুরসি আসমান ও জমিন জুড়ে বিস্তৃত, আর এ দুটির রক্ষণাবেক্ষণ তাঁকে ক্লান্ত করে না। তিনি সুউচ্চ, মহান।"}', '{"en": "Whoever recites it before sleeping remains under Allah’s protection until morning.", "bn": "ঘুমানোর আগে পড়লে সকাল পর্যন্ত আল্লাহর পক্ষ থেকে একজন রক্ষাকারী থাকে।"}', '{"en": "Morning, evening, after each salah and before sleeping", "bn": "সকাল-সন্ধ্যায়, প্রতি নামাজের পর ও ঘুমানোর আগে"}', 1, 'Quran 2:255; Sahih al-Bukhari 2311 (before sleep)', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
