INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('5be4794b-ea22-5a41-a52d-9a6c52ed193b', '{"en": "The three Quls (al-Ikhlas, al-Falaq, an-Nas)", "bn": "তিন কুল (ইখলাস, ফালাক, নাস)"}', 'قُلْ هُوَ ٱللَّهُ أَحَدٌ ﴿١﴾ ٱللَّهُ ٱلصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ ﴿٤﴾ ۞ قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾ ۞ قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴿١﴾ مَلِكِ ٱلنَّاسِ ﴿٢﴾ إِلَٰهِ ٱلنَّاسِ ﴿٣﴾ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ﴿٤﴾ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ ﴿٥﴾ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ ﴿٦﴾', '{"en": "Qul huwallahu ahad… / Qul a‘udhu bi rabbil-falaq… / Qul a‘udhu bi rabbin-nas…", "bn": "কুল হুওয়াল্লাহু আহাদ… / কুল আউযু বিরব্বিল ফালাক… / কুল আউযু বিরব্বিন নাস…"}', '{"en": "Surahs 112, 113 and 114: Allah is One; and seeking refuge with the Lord of daybreak and the Lord of mankind from every evil.", "bn": "সূরা ১১২, ১১৩ ও ১১৪: আল্লাহ এক; এবং প্রভাতের রব ও মানুষের রবের কাছে সব অনিষ্ট থেকে আশ্রয় চাওয়া।"}', '{"en": "They suffice you against everything.", "bn": "এগুলো সবকিছুর জন্য আপনার জন্য যথেষ্ট হবে।"}', '{"en": "Three times each, morning and evening; and before sleeping", "bn": "সকাল-সন্ধ্যায় প্রতিটি তিনবার; ঘুমানোর আগেও"}', 3, 'Quran 112–114; Sunan Abi Dawud 5082; Jami‘ at-Tirmidhi 3575', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
