INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('d59cc654-51da-5767-af26-f8f51110a0cc', '{"en": "The master supplication for forgiveness", "bn": "সাইয়্যিদুল ইস্তিগফার"}', 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', '{"en": "Allahumma anta rabbi la ilaha illa ant, khalaqtani wa ana ‘abduk, wa ana ‘ala ‘ahdika wa wa‘dika mastata‘t, a‘udhu bika min sharri ma sana‘t, abu’u laka bi ni‘matika ‘alayya, wa abu’u laka bi dhanbi, faghfir li, fa innahu la yaghfirudh-dhunuba illa ant", "bn": "আল্লাহুম্মা আনতা রব্বি লা ইলাহা ইল্লা আনতা, খালাকতানি ওয়া আনা আবদুকা, ওয়া আনা আলা আহদিকা ওয়া ওয়াদিকা মাসতাতাতু, আউযু বিকা মিন শাররি মা সানাতু, আবুউ লাকা বিনিমাতিকা আলাইয়া, ওয়া আবুউ লাকা বিযামবি, ফাগফির লি, ফাইন্নাহু লা ইয়াগফিরুয যুনুবা ইল্লা আনতা"}', '{"en": "O Allah, You are my Lord; there is no god but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You.", "bn": "হে আল্লাহ, আপনি আমার রব; আপনি ছাড়া কোনো উপাস্য নেই। আপনি আমাকে সৃষ্টি করেছেন, আমি আপনার বান্দা। আমি সাধ্যমতো আপনার অঙ্গীকার ও প্রতিশ্রুতির ওপর আছি। আমি যা করেছি তার অনিষ্ট থেকে আপনার আশ্রয় চাই। আমার ওপর আপনার নিয়ামত স্বীকার করছি এবং আমার গুনাহও স্বীকার করছি; তাই আমাকে ক্ষমা করুন, কারণ আপনি ছাড়া কেউ গুনাহ ক্ষমা করে না।"}', '{"en": "Whoever says it with conviction and dies that day or night will be among the people of Paradise.", "bn": "দৃঢ় বিশ্বাসের সাথে পড়ে সেদিন বা সে রাতে মারা গেলে জান্নাতি হবে।"}', '{"en": "Once in the morning and once in the evening", "bn": "সকালে একবার ও সন্ধ্যায় একবার"}', 1, 'Sahih al-Bukhari 6306', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
