INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('235ef585-7c9c-54e8-b78b-6d628e64fa36', '{"en": "In the name of Allah, with whose name nothing harms", "bn": "আল্লাহর নামে, যাঁর নামে কিছুই ক্ষতি করতে পারে না"}', 'بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ، وَهُوَ السَّمِيعُ الْعَلِيمُ', '{"en": "Bismillahil-ladhi la yadurru ma‘asmihi shay’un fil-ardi wa la fis-sama’, wa huwas-sami‘ul-‘alim", "bn": "বিসমিল্লাহিল্লাযি লা ইয়াদুররু মাআসমিহি শাইউন ফিল আরদি ওয়ালা ফিস সামাই, ওয়া হুওয়াস সামিউল আলিম"}', '{"en": "In the name of Allah, with whose name nothing on earth or in the heaven can cause harm, and He is the All-Hearing, the All-Knowing.", "bn": "আল্লাহর নামে, যাঁর নামের সাথে জমিনে বা আসমানে কোনো কিছুই ক্ষতি করতে পারে না; তিনি সর্বশ্রোতা, সর্বজ্ঞ।"}', '{"en": "Nothing will harm the one who says it.", "bn": "যে এটি পড়ে, কিছুই তার ক্ষতি করতে পারবে না।"}', '{"en": "Three times in the morning and three in the evening", "bn": "সকালে তিনবার ও সন্ধ্যায় তিনবার"}', 3, 'Sunan Abi Dawud 5088; Jami‘ at-Tirmidhi 3388', 'hasan', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '235ef585-7c9c-54e8-b78b-6d628e64fa36', 4 FROM is_dua_categories WHERE slug = 'morning' ON CONFLICT DO NOTHING;
