INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('034aee18-fbe2-51dd-8c0e-ba889cdc9f99', '{"en": "Refuge in Allah’s perfect words", "bn": "আল্লাহর পরিপূর্ণ বাণীর আশ্রয়"}', 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', '{"en": "A‘udhu bi kalimatillahit-tammati min sharri ma khalaq", "bn": "আউযু বিকালিমাতিল্লাহিত তাম্মাতি মিন শাররি মা খালাক"}', '{"en": "I seek refuge in the perfect words of Allah from the evil of what He has created.", "bn": "আমি আল্লাহর পরিপূর্ণ বাণীসমূহের মাধ্যমে তাঁর সৃষ্টির অনিষ্ট থেকে আশ্রয় চাই।"}', '{}', '{"en": "Three times in the evening; and when stopping at a place", "bn": "সন্ধ্যায় তিনবার; কোথাও যাত্রাবিরতি করলে"}', 3, 'Sahih Muslim 2708, 2709', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '034aee18-fbe2-51dd-8c0e-ba889cdc9f99', 5 FROM is_dua_categories WHERE slug = 'evening' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('ee7d16e3-5370-557c-9604-1b5d2f50c50f', '{"en": "Glory and praise be to Allah", "bn": "সুবহানাল্লাহি ওয়া বিহামদিহি"}', 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', '{"en": "SubhanAllahi wa bihamdihi", "bn": "সুবহানাল্লাহি ওয়া বিহামদিহি"}', '{"en": "Glory be to Allah and praise be to Him.", "bn": "আল্লাহ পবিত্র, এবং সব প্রশংসা তাঁরই।"}', '{"en": "No one brings anything better on the Day of Resurrection, except one who said the same or more.", "bn": "কিয়ামতের দিন এর চেয়ে উত্তম কিছু কেউ আনতে পারবে না, তবে যে এর সমান বা বেশি বলেছে সে ছাড়া।"}', '{"en": "A hundred times in the morning and in the evening", "bn": "সকালে ও সন্ধ্যায় একশবার"}', 100, 'Sahih Muslim 2692', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
