INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'ee7d16e3-5370-557c-9604-1b5d2f50c50f', 6 FROM is_dua_categories WHERE slug = 'evening' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('a758d919-9f1c-5124-835d-38250a450fb4', '{"en": "O Allah, by You we enter the morning", "bn": "হে আল্লাহ, আপনার নামে আমাদের সকাল"}', 'اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ', '{"en": "Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namutu, wa ilaykan-nushur", "bn": "আল্লাহুম্মা বিকা আসবাহনা, ওয়া বিকা আমসাইনা, ওয়া বিকা নাহইয়া, ওয়া বিকা নামুতু, ওয়া ইলাইকান নুশুর"}', '{"en": "O Allah, by You we enter the morning and by You we enter the evening, by You we live and by You we die, and to You is the resurrection.", "bn": "হে আল্লাহ, আপনার নামেই আমরা সকালে উপনীত হই ও সন্ধ্যায় উপনীত হই, আপনার নামেই বাঁচি ও মরি, আর আপনার দিকেই পুনরুত্থান।"}', '{}', '{"en": "In the morning (in the evening say “by You we enter the evening… and to You is the return”)", "bn": "সকালে (সন্ধ্যায় শব্দক্রম বদলে “ওয়া ইলাইকাল মাসির” বলবেন)"}', 1, 'Jami‘ at-Tirmidhi 3391; Sunan Abi Dawud 5068', 'hasan', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'a758d919-9f1c-5124-835d-38250a450fb4', 7 FROM is_dua_categories WHERE slug = 'morning' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('d0ff341a-f8f7-573b-9e28-38b59807a38b', '{"en": "O Ever-Living, O Sustainer", "bn": "ইয়া হাইয়ু ইয়া কাইয়ুম"}', 'يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ', '{"en": "Ya Hayyu ya Qayyum, bi rahmatika astaghith, aslih li sha’ni kullah, wa la takilni ila nafsi tarfata ‘ayn", "bn": "ইয়া হাইয়ু ইয়া কাইয়ুম, বিরহমাতিকা আসতাগিস, আসলিহ লি শানি কুল্লাহু, ওয়ালা তাকিলনি ইলা নাফসি তারফাতা আইন"}', '{"en": "O Ever-Living, O Sustainer of all, by Your mercy I seek help: set right all my affairs, and do not leave me to myself even for the blink of an eye.", "bn": "হে চিরঞ্জীব, হে সবকিছুর ধারক, আপনার রহমতের উসিলায় সাহায্য চাই: আমার সব বিষয় ঠিক করে দিন, আর এক পলকের জন্যও আমাকে আমার নিজের ওপর ছেড়ে দেবেন না।"}', '{}', '{"en": "Morning and evening, and in hardship", "bn": "সকাল-সন্ধ্যায় ও বিপদের সময়"}', 1, 'an-Nasa’i, as-Sunan al-Kubra; al-Hakim, al-Mustadrak', 'hasan', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'd0ff341a-f8f7-573b-9e28-38b59807a38b', 8 FROM is_dua_categories WHERE slug = 'morning' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'd0ff341a-f8f7-573b-9e28-38b59807a38b', 8 FROM is_dua_categories WHERE slug = 'evening' ON CONFLICT DO NOTHING;
