INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('eed285dc-b2c6-54fc-9e17-b350bd8640a0', '{"en": "On waking up", "bn": "ঘুম থেকে উঠে"}', 'الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', '{"en": "Alhamdu lillahil-ladhi ahyana ba‘da ma amatana wa ilayhin-nushur", "bn": "আলহামদু লিল্লাহিল্লাযি আহইয়ানা বাদা মা আমাতানা ওয়া ইলাইহিন নুশুর"}', '{"en": "All praise is for Allah who gave us life after causing us to die, and to Him is the resurrection.", "bn": "সব প্রশংসা আল্লাহর, যিনি আমাদের মৃত্যুর (ঘুমের) পর জীবিত করেছেন, আর তাঁর দিকেই পুনরুত্থান।"}', '{}', '{"en": "When you wake up", "bn": "ঘুম থেকে জেগে"}', 1, 'Sahih al-Bukhari 6312', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'eed285dc-b2c6-54fc-9e17-b350bd8640a0', 9 FROM is_dua_categories WHERE slug = 'waking' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('cb587221-99be-5cac-af51-5d685a961b45', '{"en": "Before sleeping", "bn": "ঘুমানোর আগে"}', 'بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا', '{"en": "Bismika Allahumma amutu wa ahya", "bn": "বিসমিকা আল্লাহুম্মা আমুতু ওয়া আহইয়া"}', '{"en": "In Your name, O Allah, I die and I live.", "bn": "হে আল্লাহ, আপনার নামেই আমি মরি (ঘুমাই) ও জীবিত হই।"}', '{}', '{"en": "When lying down to sleep", "bn": "শোয়ার সময়"}', 1, 'Sahih al-Bukhari 6324', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'cb587221-99be-5cac-af51-5d685a961b45', 10 FROM is_dua_categories WHERE slug = 'sleep' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('e054a697-5949-52fa-9b06-4ed194300544', '{"en": "Protect me from Your punishment", "bn": "আপনার শাস্তি থেকে আমাকে রক্ষা করুন"}', 'اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ', '{"en": "Allahumma qini ‘adhabaka yawma tab‘athu ‘ibadak", "bn": "আল্লাহুম্মা কিনি আযাবাকা ইয়াওমা তাবআসু ইবাদাক"}', '{"en": "O Allah, protect me from Your punishment on the day You resurrect Your servants.", "bn": "হে আল্লাহ, যেদিন আপনি আপনার বান্দাদের পুনরুত্থিত করবেন, সেদিন আমাকে আপনার শাস্তি থেকে রক্ষা করুন।"}', '{}', '{"en": "Lying on the right side, hand under the cheek", "bn": "ডান কাতে শুয়ে, গালের নিচে হাত রেখে"}', 3, 'Sunan Abi Dawud 5045; Jami‘ at-Tirmidhi 3398', 'hasan', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'e054a697-5949-52fa-9b06-4ed194300544', 11 FROM is_dua_categories WHERE slug = 'sleep' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('379f5dcb-5250-5c58-bc3a-2df031e1144f', '{"en": "Right after the salam", "bn": "সালাম ফেরানোর পরপর"}', 'أَسْتَغْفِرُ اللَّهَ (ثَلَاثًا)، اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ', '{"en": "Astaghfirullah (3 times). Allahumma antas-salam wa minkas-salam, tabarakta ya dhal-jalali wal-ikram", "bn": "আস্তাগফিরুল্লাহ (তিনবার)। আল্লাহুম্মা আনতাস সালাম, ওয়া মিনকাস সালাম, তাবারাকতা ইয়া যাল জালালি ওয়াল ইকরাম"}', '{"en": "I seek Allah’s forgiveness (three times). O Allah, You are Peace and from You is peace. Blessed are You, O Owner of majesty and honour.", "bn": "আমি আল্লাহর কাছে ক্ষমা চাই (তিনবার)। হে আল্লাহ, আপনিই শান্তি, আপনার কাছ থেকেই শান্তি। আপনি বরকতময়, হে মহিমা ও সম্মানের অধিকারী।"}', '{}', '{"en": "After every obligatory salah", "bn": "প্রতি ফরজ নামাজের পর"}', 1, 'Sahih Muslim 591', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '379f5dcb-5250-5c58-bc3a-2df031e1144f', 12 FROM is_dua_categories WHERE slug = 'after-salah' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('30770934-4ba3-545f-b31e-e6b5605a0ec6', '{"en": "None can withhold what You give", "bn": "আপনি যা দেন কেউ তা আটকাতে পারে না"}', 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ', '{"en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ‘ala kulli shay’in qadir. Allahumma la mani‘a lima a‘tayt, wa la mu‘tiya lima mana‘t, wa la yanfa‘u dhal-jaddi minkal-jadd", "bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু ওয়া হুওয়া আলা কুল্লি শাইয়িন কাদির। আল্লাহুম্মা লা মানিআ লিমা আতাইতা, ওয়ালা মুতিয়া লিমা মানাতা, ওয়ালা ইয়ানফাউ যাল জাদ্দি মিনকাল জাদ্দু"}', '{"en": "There is no god but Allah alone, without partner; His is the dominion and His the praise, and He has power over all things. O Allah, none can withhold what You give, none can give what You withhold, and no wealth or rank avails anyone against You.", "bn": "আল্লাহ ছাড়া কোনো উপাস্য নেই, তিনি এক, তাঁর কোনো শরিক নেই; রাজত্ব ও প্রশংসা তাঁরই, তিনি সবকিছুর ওপর ক্ষমতাবান। হে আল্লাহ, আপনি যা দেন তা কেউ আটকাতে পারে না, আর যা আটকান তা কেউ দিতে পারে না; আপনার কাছে কোনো সম্পদশালীর সম্পদ কাজে আসে না।"}', '{}', '{"en": "After every obligatory salah", "bn": "প্রতি ফরজ নামাজের পর"}', 1, 'Sahih al-Bukhari 844; Sahih Muslim 593', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '30770934-4ba3-545f-b31e-e6b5605a0ec6', 13 FROM is_dua_categories WHERE slug = 'after-salah' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('65efa62b-7e88-5ea3-aa9d-e0ec54e59bf4', '{"en": "Help me remember You", "bn": "আপনার জিকিরে আমাকে সাহায্য করুন"}', 'اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ', '{"en": "Allahumma a‘inni ‘ala dhikrika wa shukrika wa husni ‘ibadatik", "bn": "আল্লাহুম্মা আইন্নি আলা যিকরিকা ওয়া শুকরিকা ওয়া হুসনি ইবাদাতিক"}', '{"en": "O Allah, help me to remember You, to thank You, and to worship You well.", "bn": "হে আল্লাহ, আপনার জিকির, শুকরিয়া ও সুন্দরভাবে ইবাদত করতে আমাকে সাহায্য করুন।"}', '{}', '{"en": "At the end of every salah", "bn": "প্রতি নামাজের শেষে"}', 1, 'Sunan Abi Dawud 1522', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '65efa62b-7e88-5ea3-aa9d-e0ec54e59bf4', 14 FROM is_dua_categories WHERE slug = 'after-salah' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('19178349-ab7f-5fac-b6e5-2a27a2915c1b', '{"en": "Leaving home", "bn": "ঘর থেকে বের হওয়ার সময়"}', 'بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', '{"en": "Bismillah, tawakkaltu ‘alallah, wa la hawla wa la quwwata illa billah", "bn": "বিসমিল্লাহি, তাওয়াক্কালতু আলাল্লাহ, ওয়ালা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ"}', '{"en": "In the name of Allah; I put my trust in Allah; there is no might nor power except with Allah.", "bn": "আল্লাহর নামে; আমি আল্লাহর ওপর ভরসা করলাম; আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই।"}', '{"en": "It is said to him: you are guided, sufficed and protected.", "bn": "তাকে বলা হয়: তুমি হেদায়াত পেলে, যথেষ্ট হলে ও রক্ষা পেলে।"}', '{"en": "When going out of the house", "bn": "ঘর থেকে বের হওয়ার সময়"}', 1, 'Sunan Abi Dawud 5095; Jami‘ at-Tirmidhi 3426', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '19178349-ab7f-5fac-b6e5-2a27a2915c1b', 15 FROM is_dua_categories WHERE slug = 'home' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('d8d9a283-0792-5745-9caf-a4c78bc33bc5', '{"en": "Before eating", "bn": "খাওয়ার আগে"}', 'بِسْمِ اللَّهِ', '{"en": "Bismillah (if you forget: Bismillahi awwalahu wa akhirah)", "bn": "বিসমিল্লাহ (ভুলে গেলে: বিসমিল্লাহি আওয়ালাহু ওয়া আখিরাহ)"}', '{"en": "In the name of Allah. (If you forget at the start: In the name of Allah, at its beginning and its end.)", "bn": "আল্লাহর নামে। (শুরুতে ভুলে গেলে: শুরু ও শেষে আল্লাহর নামে।)"}', '{}', '{"en": "Before starting to eat", "bn": "খাওয়া শুরু করার আগে"}', 1, 'Sunan Abi Dawud 3767; Jami‘ at-Tirmidhi 1858', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'd8d9a283-0792-5745-9caf-a4c78bc33bc5', 16 FROM is_dua_categories WHERE slug = 'food' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('062d9f5f-1fc6-5bf5-bf72-0b2de184163f', '{"en": "After eating", "bn": "খাওয়ার পর"}', 'الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', '{"en": "Alhamdu lillahil-ladhi at‘amani hadha, wa razaqanihi min ghayri hawlin minni wa la quwwah", "bn": "আলহামদু লিল্লাহিল্লাযি আতআমানি হাযা, ওয়া রাযাকানিহি মিন গাইরি হাওলিম মিন্নি ওয়ালা কুওয়াহ"}', '{"en": "All praise is for Allah who fed me this and provided it for me without any might or power on my part.", "bn": "সব প্রশংসা আল্লাহর, যিনি আমাকে এটি খাইয়েছেন এবং আমার কোনো শক্তি-সামর্থ্য ছাড়াই আমাকে এ রিজিক দিয়েছেন।"}', '{"en": "His previous sins are forgiven.", "bn": "তার আগের গুনাহ ক্ষমা করা হয়।"}', '{"en": "When you finish eating", "bn": "খাওয়া শেষে"}', 1, 'Sunan Abi Dawud 4023; Jami‘ at-Tirmidhi 3458', 'hasan', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '062d9f5f-1fc6-5bf5-bf72-0b2de184163f', 17 FROM is_dua_categories WHERE slug = 'food' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('af99c621-e010-5214-8058-6f5e5afa90f7', '{"en": "On breaking the fast", "bn": "ইফতারের সময়"}', 'ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ', '{"en": "Dhahabaz-zama’u, wabtallatil-‘uruqu, wa thabatal-ajru in sha’ Allah", "bn": "যাহাবাজ জামাউ, ওয়াবতাল্লাতিল উরুকু, ওয়া সাবাতাল আজরু ইনশাআল্লাহ"}', '{"en": "The thirst has gone, the veins are moistened, and the reward is certain, if Allah wills.", "bn": "তৃষ্ণা দূর হলো, শিরাগুলো সিক্ত হলো, আর ইনশাআল্লাহ সওয়াব নিশ্চিত হলো।"}', '{}', '{"en": "After breaking the fast", "bn": "ইফতারের পর"}', 1, 'Sunan Abi Dawud 2357', 'hasan', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'af99c621-e010-5214-8058-6f5e5afa90f7', 18 FROM is_dua_categories WHERE slug = 'food' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('3e2b2401-65d9-53cb-ba55-d1396e706898', '{"en": "When riding or setting off on a journey", "bn": "যানবাহনে চড়ে বা সফর শুরু করে"}', 'سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', '{"en": "Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila rabbina lamunqalibun", "bn": "সুবহানাল্লাযি সাখখারা লানা হাযা ওয়ামা কুন্না লাহু মুকরিনিন, ওয়া ইন্না ইলা রব্বিনা লামুনকালিবুন"}', '{"en": "Glory be to Him who has made this subservient to us, and we could not have done it ourselves; and to our Lord we will surely return.", "bn": "পবিত্র তিনি, যিনি একে আমাদের অধীন করে দিয়েছেন, অথচ আমরা একে বশ করতে সক্ষম ছিলাম না; আর নিশ্চয়ই আমরা আমাদের রবের কাছে ফিরে যাব।"}', '{}', '{"en": "On a vehicle or mount, at the start of travel", "bn": "যানবাহনে উঠে, সফরের শুরুতে"}', 1, 'Quran 43:13–14; Sahih Muslim 1342', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '3e2b2401-65d9-53cb-ba55-d1396e706898', 19 FROM is_dua_categories WHERE slug = 'travel' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '3e2b2401-65d9-53cb-ba55-d1396e706898', 19 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('024d2465-e2b4-5036-b8ef-1b9df7bf4d0f', '{"en": "Entering the masjid", "bn": "মসজিদে প্রবেশের সময়"}', 'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ', '{"en": "Allahummaf-tah li abwaba rahmatik", "bn": "আল্লাহুম্মাফ তাহলি আবওয়াবা রহমাতিক"}', '{"en": "O Allah, open for me the doors of Your mercy.", "bn": "হে আল্লাহ, আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন।"}', '{}', '{"en": "Entering with the right foot", "bn": "ডান পা দিয়ে প্রবেশ করে"}', 1, 'Sahih Muslim 713', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '024d2465-e2b4-5036-b8ef-1b9df7bf4d0f', 20 FROM is_dua_categories WHERE slug = 'masjid' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('d51b4a0b-884d-5338-8305-2c27df17e489', '{"en": "Leaving the masjid", "bn": "মসজিদ থেকে বের হওয়ার সময়"}', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ', '{"en": "Allahumma inni as’aluka min fadlik", "bn": "আল্লাহুম্মা ইন্নি আসআলুকা মিন ফাদলিক"}', '{"en": "O Allah, I ask You of Your bounty.", "bn": "হে আল্লাহ, আমি আপনার অনুগ্রহ প্রার্থনা করি।"}', '{}', '{"en": "Leaving with the left foot", "bn": "বাম পা দিয়ে বের হয়ে"}', 1, 'Sahih Muslim 713', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'd51b4a0b-884d-5338-8305-2c27df17e489', 21 FROM is_dua_categories WHERE slug = 'masjid' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('9297e832-2c70-5b80-9b24-dc2af09a0e03', '{"en": "Before wudu", "bn": "অজুর শুরুতে"}', 'بِسْمِ اللَّهِ', '{"en": "Bismillah", "bn": "বিসমিল্লাহ"}', '{"en": "In the name of Allah.", "bn": "আল্লাহর নামে।"}', '{}', '{"en": "At the start of wudu", "bn": "অজুর শুরুতে"}', 1, 'Sunan Abi Dawud 101', 'hasan', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '9297e832-2c70-5b80-9b24-dc2af09a0e03', 22 FROM is_dua_categories WHERE slug = 'wudu' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('0cee2e82-20d3-5d20-8533-61d48296421d', '{"en": "After wudu", "bn": "অজুর পর"}', 'أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ', '{"en": "Ashhadu an la ilaha illallahu wahdahu la sharika lah, wa ashhadu anna Muhammadan ‘abduhu wa rasuluh", "bn": "আশহাদু আল লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ"}', '{"en": "I bear witness that there is no god but Allah alone, without partner, and I bear witness that Muhammad is His servant and Messenger.", "bn": "আমি সাক্ষ্য দিচ্ছি যে আল্লাহ ছাড়া কোনো উপাস্য নেই, তিনি এক, তাঁর কোনো শরিক নেই; এবং সাক্ষ্য দিচ্ছি যে মুহাম্মাদ তাঁর বান্দা ও রাসুল।"}', '{"en": "The eight gates of Paradise are opened for him; he may enter by whichever he wishes.", "bn": "তার জন্য জান্নাতের আটটি দরজা খুলে দেওয়া হয়; যেটি দিয়ে ইচ্ছা প্রবেশ করবে।"}', '{"en": "On finishing wudu", "bn": "অজু শেষ করে"}', 1, 'Sahih Muslim 234', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '0cee2e82-20d3-5d20-8533-61d48296421d', 23 FROM is_dua_categories WHERE slug = 'wudu' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('de092aa8-c83d-59cf-9dee-e10c7151d33e', '{"en": "In distress", "bn": "বিপদ ও কষ্টের সময়"}', 'لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ', '{"en": "La ilaha illallahul-‘azimul-halim, la ilaha illallahu rabbul-‘arshil-‘azim, la ilaha illallahu rabbus-samawati wa rabbul-ardi wa rabbul-‘arshil-karim", "bn": "লা ইলাহা ইল্লাল্লাহুল আযিমুল হালিম, লা ইলাহা ইল্লাল্লাহু রব্বুল আরশিল আযিম, লা ইলাহা ইল্লাল্লাহু রব্বুস সামাওয়াতি ওয়া রব্বুল আরদি ওয়া রব্বুল আরশিল কারিম"}', '{"en": "There is no god but Allah, the Mighty, the Forbearing. There is no god but Allah, Lord of the mighty Throne. There is no god but Allah, Lord of the heavens, Lord of the earth and Lord of the noble Throne.", "bn": "আল্লাহ ছাড়া কোনো উপাস্য নেই, তিনি মহান, সহনশীল। আল্লাহ ছাড়া কোনো উপাস্য নেই, তিনি মহান আরশের রব। আল্লাহ ছাড়া কোনো উপাস্য নেই, তিনি আসমানসমূহের রব, জমিনের রব ও সম্মানিত আরশের রব।"}', '{}', '{"en": "When in hardship or distress", "bn": "কঠিন সময় ও দুশ্চিন্তায়"}', 1, 'Sahih al-Bukhari 6346; Sahih Muslim 2730', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'de092aa8-c83d-59cf-9dee-e10c7151d33e', 24 FROM is_dua_categories WHERE slug = 'distress' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('1ff84acd-ffd3-588a-9694-d260a2cb5563', '{"en": "The supplication of Yunus (Jonah)", "bn": "ইউনুস (আ.)-এর দোয়া"}', 'لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ', '{"en": "La ilaha illa anta subhanaka inni kuntu minaz-zalimin", "bn": "লা ইলাহা ইল্লা আনতা সুবহানাকা ইন্নি কুনতু মিনাজ জালিমিন"}', '{"en": "There is no god but You. Glory be to You! I have indeed been among the wrongdoers.", "bn": "আপনি ছাড়া কোনো উপাস্য নেই, আপনি পবিত্র; নিশ্চয়ই আমি জালিমদের অন্তর্ভুক্ত ছিলাম।"}', '{"en": "No Muslim calls upon Allah with it for anything except that Allah answers him.", "bn": "কোনো মুসলিম এ দোয়া দিয়ে কিছু চাইলে আল্লাহ তার দোয়া কবুল করেন।"}', '{"en": "In any difficulty", "bn": "যেকোনো বিপদে"}', 1, 'Quran 21:87; Jami‘ at-Tirmidhi 3505', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '1ff84acd-ffd3-588a-9694-d260a2cb5563', 25 FROM is_dua_categories WHERE slug = 'distress' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '1ff84acd-ffd3-588a-9694-d260a2cb5563', 25 FROM is_dua_categories WHERE slug = 'forgiveness' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '1ff84acd-ffd3-588a-9694-d260a2cb5563', 25 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('20dfce87-d9f4-527d-94f4-6f69a1ebafc2', '{"en": "Against worry and grief", "bn": "দুশ্চিন্তা ও দুঃখ থেকে আশ্রয়"}', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ', '{"en": "Allahumma inni a‘udhu bika minal-hammi wal-hazan, wal-‘ajzi wal-kasal, wal-bukhli wal-jubn, wa dala‘id-dayni wa ghalabatir-rijal", "bn": "আল্লাহুম্মা ইন্নি আউযু বিকা মিনাল হাম্মি ওয়াল হাযান, ওয়াল আজযি ওয়াল কাসাল, ওয়াল বুখলি ওয়াল জুবন, ওয়া দালাইদ দাইনি ওয়া গালাবাতির রিজাল"}', '{"en": "O Allah, I seek refuge in You from worry and grief, from helplessness and laziness, from miserliness and cowardice, and from the burden of debt and being overpowered by people.", "bn": "হে আল্লাহ, আমি আপনার কাছে আশ্রয় চাই দুশ্চিন্তা ও দুঃখ থেকে, অক্ষমতা ও অলসতা থেকে, কৃপণতা ও কাপুরুষতা থেকে, এবং ঋণের বোঝা ও মানুষের দমন থেকে।"}', '{}', '{"en": "Any time, especially when worried", "bn": "যেকোনো সময়, বিশেষত দুশ্চিন্তায়"}', 1, 'Sahih al-Bukhari 6369', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '20dfce87-d9f4-527d-94f4-6f69a1ebafc2', 26 FROM is_dua_categories WHERE slug = 'distress' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('14e99dde-8b64-53c7-bdca-290679064c59', '{"en": "Allah is sufficient for us", "bn": "আল্লাহই আমাদের জন্য যথেষ্ট"}', 'حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', '{"en": "Hasbunallahu wa ni‘mal-wakil", "bn": "হাসবুনাল্লাহু ওয়া নিমাল ওয়াকিল"}', '{"en": "Allah is sufficient for us, and He is the best disposer of affairs.", "bn": "আল্লাহই আমাদের জন্য যথেষ্ট, আর তিনি কতই না উত্তম কর্মবিধায়ক।"}', '{}', '{"en": "When afraid or facing a threat", "bn": "ভয় বা বিপদের মুখে"}', 1, 'Quran 3:173; Sahih al-Bukhari 4563', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '14e99dde-8b64-53c7-bdca-290679064c59', 27 FROM is_dua_categories WHERE slug = 'distress' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '14e99dde-8b64-53c7-bdca-290679064c59', 27 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('2c0d7339-3c11-582a-b5f1-7db7ecc7acf1', '{"en": "Lord, forgive me and accept my repentance", "bn": "হে রব, আমাকে ক্ষমা করুন ও তওবা কবুল করুন"}', 'رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ', '{"en": "Rabbighfir li wa tub ‘alayya, innaka antat-tawwabur-rahim", "bn": "রব্বিগফির লি ওয়া তুব আলাইয়া, ইন্নাকা আনতাত তাওয়াবুর রহিম"}', '{"en": "My Lord, forgive me and accept my repentance; You are the Accepter of repentance, the Most Merciful.", "bn": "হে আমার রব, আমাকে ক্ষমা করুন ও আমার তওবা কবুল করুন; নিশ্চয়ই আপনি তওবা কবুলকারী, পরম দয়ালু।"}', '{}', '{"en": "Often; the Prophet ﷺ was heard saying it a hundred times in one sitting", "bn": "বেশি বেশি; নবী ﷺ এক বৈঠকে একশবার বলতেন"}', 100, 'Sunan Abi Dawud 1516; Jami‘ at-Tirmidhi 3434', 'sahih', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '2c0d7339-3c11-582a-b5f1-7db7ecc7acf1', 28 FROM is_dua_categories WHERE slug = 'forgiveness' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('876c008f-120a-5fad-bbcb-f08f65d51f9e', '{"en": "The supplication of Adam and Hawwa", "bn": "আদম ও হাওয়া (আ.)-এর দোয়া"}', 'رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', '{"en": "Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal-khasirin", "bn": "রব্বানা জালামনা আনফুসানা ওয়া ইল্লাম তাগফির লানা ওয়া তারহামনা লানাকুনান্না মিনাল খাসিরিন"}', '{"en": "Our Lord, we have wronged ourselves; if You do not forgive us and have mercy on us, we will surely be among the losers.", "bn": "হে আমাদের রব, আমরা নিজেদের ওপর জুলুম করেছি; আপনি যদি আমাদের ক্ষমা না করেন ও দয়া না করেন, তবে অবশ্যই আমরা ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হব।"}', '{}', '{"en": "When asking forgiveness", "bn": "ক্ষমা চাওয়ার সময়"}', 1, 'Quran 7:23', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '876c008f-120a-5fad-bbcb-f08f65d51f9e', 29 FROM is_dua_categories WHERE slug = 'forgiveness' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '876c008f-120a-5fad-bbcb-f08f65d51f9e', 29 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('d0cb3acd-26b0-5158-ad30-0e1cd3807d33', '{"en": "Good in this world and the Hereafter", "bn": "দুনিয়া ও আখিরাতের কল্যাণ"}', 'رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْءَاخِرَةِ حَسَنَةًۭ وَقِنَا عَذَابَ ٱلنَّارِ', '{"en": "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina ‘adhaban-nar", "bn": "রব্বানা আতিনা ফিদ দুনইয়া হাসানাতান ওয়া ফিল আখিরাতি হাসানাতান ওয়া কিনা আযাবান নার"}', '{"en": "Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.", "bn": "হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতেও কল্যাণ দিন, এবং আমাদের জাহান্নামের আজাব থেকে রক্ষা করুন।"}', '{}', '{"en": "Any time; the Prophet ﷺ said it most often", "bn": "যেকোনো সময়; নবী ﷺ এটি সবচেয়ে বেশি পড়তেন"}', 1, 'Quran 2:201; Sahih al-Bukhari 6389', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'd0cb3acd-26b0-5158-ad30-0e1cd3807d33', 30 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'd0cb3acd-26b0-5158-ad30-0e1cd3807d33', 30 FROM is_dua_categories WHERE slug = 'after-salah' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('207fe5ce-7250-5339-9686-4807ed19160b', '{"en": "Do not burden us beyond our strength", "bn": "আমাদের সাধ্যের বাইরে বোঝা দেবেন না"}', 'رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًۭا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '{"en": "Rabbana la tu’akhidhna in nasina aw akhta’na…", "bn": "রব্বানা লা তুআখিযনা ইন নাসিনা আও আখতানা…"}', '{"en": "Our Lord, do not take us to task if we forget or err. Our Lord, do not place on us a burden like that You placed on those before us. Our Lord, do not burden us with what we cannot bear. Pardon us, forgive us and have mercy on us. You are our Protector, so help us against the disbelieving people.", "bn": "হে আমাদের রব, আমরা ভুলে গেলে বা ভুল করলে আমাদের পাকড়াও করবেন না। হে আমাদের রব, আমাদের ওপর এমন বোঝা চাপাবেন না যেমন আমাদের পূর্ববর্তীদের ওপর চাপিয়েছিলেন। হে আমাদের রব, যা বহনের সাধ্য আমাদের নেই তা আমাদের ওপর চাপাবেন না। আমাদের মাফ করুন, ক্ষমা করুন ও দয়া করুন। আপনিই আমাদের অভিভাবক; সুতরাং কাফির সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করুন।"}', '{"en": "Whoever recites the last two ayahs of al-Baqarah at night, they suffice him.", "bn": "রাতে সূরা বাকারার শেষ দুই আয়াত পড়লে তা তার জন্য যথেষ্ট হয়।"}', '{"en": "At night (the last two ayahs of al-Baqarah)", "bn": "রাতে (সূরা বাকারার শেষ দুই আয়াত)"}', 1, 'Quran 2:286; Sahih al-Bukhari 5009', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '207fe5ce-7250-5339-9686-4807ed19160b', 31 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('28696fbd-b291-5d8f-860a-57f1c1312bf7', '{"en": "Keep our hearts steady", "bn": "আমাদের অন্তর অবিচল রাখুন"}', 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ', '{"en": "Rabbana la tuzigh qulubana ba‘da idh hadaytana wa hab lana min ladunka rahmah, innaka antal-wahhab", "bn": "রব্বানা লা তুযিগ কুলুবানা বাদা ইয হাদাইতানা ওয়া হাবলানা মিল্লাদুনকা রহমাহ, ইন্নাকা আনতাল ওয়াহহাব"}', '{"en": "Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself. You are the Bestower.", "bn": "হে আমাদের রব, হেদায়াত দেওয়ার পর আমাদের অন্তরকে বাঁকা করবেন না, এবং আপনার পক্ষ থেকে আমাদের রহমত দান করুন; নিশ্চয়ই আপনি মহাদাতা।"}', '{}', '{"en": "Any time", "bn": "যেকোনো সময়"}', 1, 'Quran 3:8', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '28696fbd-b291-5d8f-860a-57f1c1312bf7', 32 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('1216ff3f-8563-56ff-ba3d-4da257995815', '{"en": "Forgiveness for me, my parents and the believers", "bn": "আমার, বাবা-মা ও মুমিনদের জন্য ক্ষমা"}', 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', '{"en": "Rabbanagh-fir li wa li walidayya wa lil-mu’minina yawma yaqumul-hisab", "bn": "রব্বানাগফির লি ওয়ালি ওয়ালিদাইয়া ওয়ালিল মুমিনিনা ইয়াওমা ইয়াকুমুল হিসাব"}', '{"en": "Our Lord, forgive me, my parents and the believers on the Day the reckoning is established.", "bn": "হে আমাদের রব, যেদিন হিসাব প্রতিষ্ঠিত হবে, সেদিন আমাকে, আমার বাবা-মাকে ও সব মুমিনকে ক্ষমা করুন।"}', '{}', '{"en": "Any time", "bn": "যেকোনো সময়"}', 1, 'Quran 14:41', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '1216ff3f-8563-56ff-ba3d-4da257995815', 33 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '1216ff3f-8563-56ff-ba3d-4da257995815', 33 FROM is_dua_categories WHERE slug = 'forgiveness' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('41cd17a0-00c8-51c7-8cd3-03657ffd168c', '{"en": "For one’s parents", "bn": "বাবা-মায়ের জন্য দোয়া"}', 'رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا', '{"en": "Rabbir-hamhuma kama rabbayani saghira", "bn": "রব্বির হামহুমা কামা রব্বায়ানি সাগিরা"}', '{"en": "My Lord, have mercy on them as they raised me when I was small.", "bn": "হে আমার রব, তাঁদের প্রতি দয়া করুন, যেমন তাঁরা শৈশবে আমাকে লালন-পালন করেছেন।"}', '{}', '{"en": "Any time", "bn": "যেকোনো সময়"}', 1, 'Quran 17:24', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '41cd17a0-00c8-51c7-8cd3-03657ffd168c', 34 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('2eb35b2c-8777-5180-8ca6-413ca40ba61d', '{"en": "The supplication of Musa (Moses)", "bn": "মুসা (আ.)-এর দোয়া"}', 'رَبِّ ٱشْرَحْ لِى صَدْرِى ﴿٢٥﴾ وَيَسِّرْ لِىٓ أَمْرِى ﴿٢٦﴾ وَٱحْلُلْ عُقْدَةًۭ مِّن لِّسَانِى ﴿٢٧﴾ يَفْقَهُوا۟ قَوْلِى ﴿٢٨﴾', '{"en": "Rabbish-rahli sadri, wa yassirli amri, wahlul ‘uqdatam-mil-lisani, yafqahu qawli", "bn": "রব্বিশ রহলি সাদরি, ওয়া ইয়াসসিরলি আমরি, ওয়াহলুল উকদাতাম মিল লিসানি, ইয়াফকাহু কাওলি"}', '{"en": "My Lord, expand my chest for me, make my task easy for me, and untie the knot from my tongue so they may understand my speech.", "bn": "হে আমার রব, আমার বক্ষ প্রশস্ত করে দিন, আমার কাজ সহজ করে দিন, এবং আমার জিহ্বার জড়তা দূর করে দিন, যাতে তারা আমার কথা বুঝতে পারে।"}', '{}', '{"en": "Before studying, speaking or a difficult task", "bn": "পড়াশোনা, কথা বলা বা কঠিন কাজের আগে"}', 1, 'Quran 20:25–28', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '2eb35b2c-8777-5180-8ca6-413ca40ba61d', 35 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('2672dbe8-7b0a-545c-ac75-c3e37fe7470d', '{"en": "Increase me in knowledge", "bn": "আমার জ্ঞান বাড়িয়ে দিন"}', 'رَّبِّ زِدْنِى عِلْمًۭا', '{"en": "Rabbi zidni ‘ilma", "bn": "রব্বি যিদনি ইলমা"}', '{"en": "My Lord, increase me in knowledge.", "bn": "হে আমার রব, আমার জ্ঞান বৃদ্ধি করে দিন।"}', '{}', '{"en": "Before and while learning", "bn": "শেখার আগে ও শেখার সময়"}', 1, 'Quran 20:114', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '2672dbe8-7b0a-545c-ac75-c3e37fe7470d', 36 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('dfc41fa8-a124-54ff-8c4c-4b2667c6dc81', '{"en": "Forgive and have mercy", "bn": "ক্ষমা করুন ও দয়া করুন"}', 'رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', '{"en": "Rabbighfir warham wa anta khayrur-rahimin", "bn": "রব্বিগফির ওয়ারহাম ওয়া আনতা খাইরুর রহিমিন"}', '{"en": "My Lord, forgive and have mercy, for You are the best of those who show mercy.", "bn": "হে আমার রব, ক্ষমা করুন ও দয়া করুন; আপনিই শ্রেষ্ঠ দয়ালু।"}', '{}', '{"en": "Any time", "bn": "যেকোনো সময়"}', 1, 'Quran 23:118', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'dfc41fa8-a124-54ff-8c4c-4b2667c6dc81', 37 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'dfc41fa8-a124-54ff-8c4c-4b2667c6dc81', 37 FROM is_dua_categories WHERE slug = 'forgiveness' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('576dd7a1-b787-57f8-8dfe-a88f13ba00d0', '{"en": "For spouses and children", "bn": "স্বামী/স্ত্রী ও সন্তানের জন্য"}', 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍۢ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', '{"en": "Rabbana hab lana min azwajina wa dhurriyyatina qurrata a‘yunin waj‘alna lil-muttaqina imama", "bn": "রব্বানা হাবলানা মিন আযওয়াজিনা ওয়া যুররিয়্যাতিনা কুররাতা আইউনিও ওয়াজআলনা লিলমুত্তাকিনা ইমামা"}', '{"en": "Our Lord, grant us in our spouses and children the comfort of our eyes, and make us leaders of the righteous.", "bn": "হে আমাদের রব, আমাদের স্ত্রী ও সন্তানদের আমাদের চোখের শীতলতা বানিয়ে দিন, এবং আমাদের মুত্তাকিদের নেতা বানিয়ে দিন।"}', '{}', '{"en": "Any time", "bn": "যেকোনো সময়"}', 1, 'Quran 25:74', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, '576dd7a1-b787-57f8-8dfe-a88f13ba00d0', 38 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_duas (id, title, arabic, transliteration, translation, virtue, when_to_read, repeat_count, source_ref, grade, review_status) VALUES ('b1386ebf-40de-54ce-8d41-5934d2ec7294', '{"en": "In need of Your good", "bn": "আপনার কল্যাণের মুখাপেক্ষী"}', 'رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍۢ فَقِيرٌۭ', '{"en": "Rabbi inni lima anzalta ilayya min khayrin faqir", "bn": "রব্বি ইন্নি লিমা আনযালতা ইলাইয়া মিন খাইরিন ফাকির"}', '{"en": "My Lord, I am in need of whatever good You send down to me.", "bn": "হে আমার রব, আপনি আমার প্রতি যে কল্যাণই নাজিল করবেন, আমি তার মুখাপেক্ষী।"}', '{}', '{"en": "When in need of provision or work", "bn": "রিজিক বা কাজের প্রয়োজনে"}', 1, 'Quran 28:24', 'quran', 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'b1386ebf-40de-54ce-8d41-5934d2ec7294', 39 FROM is_dua_categories WHERE slug = 'quran' ON CONFLICT DO NOTHING;
INSERT INTO is_dua_category_items (category_id, dua_id, sort_order) SELECT id, 'b1386ebf-40de-54ce-8d41-5934d2ec7294', 39 FROM is_dua_categories WHERE slug = 'distress' ON CONFLICT DO NOTHING;
INSERT INTO is_dhikr_presets (id, arabic, transliteration, translation, default_target, virtue, source_ref, review_status, sort_order) VALUES ('3c5c820e-102b-5d1b-95fc-3bd955c55bc3', 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', '{"en": "SubhanAllahi wa bihamdihi", "bn": "সুবহানাল্লাহি ওয়া বিহামদিহি"}', '{"en": "Glory be to Allah and praise be to Him", "bn": "আল্লাহ পবিত্র, সব প্রশংসা তাঁর"}', 100, '{"en": "Said a hundred times a day, sins are wiped away even if they are like the foam of the sea.", "bn": "দিনে একশবার বললে সমুদ্রের ফেনার মতো গুনাহও মাফ হয়ে যায়।"}', 'Sahih al-Bukhari 6405', 'in_review', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dhikr_presets (id, arabic, transliteration, translation, default_target, virtue, source_ref, review_status, sort_order) VALUES ('b7de9282-2157-5103-b866-ef6f7b14422d', 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ', '{"en": "SubhanAllahi wa bihamdihi, SubhanAllahil-‘Azim", "bn": "সুবহানাল্লাহি ওয়া বিহামদিহি, সুবহানাল্লাহিল আযিম"}', '{"en": "Glory and praise be to Allah; glory be to Allah, the Almighty", "bn": "আল্লাহ পবিত্র ও প্রশংসিত; মহান আল্লাহ পবিত্র"}', 33, '{"en": "Two phrases light on the tongue, heavy on the Scale, beloved to the Most Merciful.", "bn": "দুটি বাক্য জিহ্বায় হালকা, মিজানে ভারী, দয়াময়ের কাছে প্রিয়।"}', 'Sahih al-Bukhari 6406; Sahih Muslim 2694', 'in_review', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dhikr_presets (id, arabic, transliteration, translation, default_target, virtue, source_ref, review_status, sort_order) VALUES ('c12167d4-9524-5faa-8b16-0bbcf35b0e24', 'لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', '{"en": "La hawla wa la quwwata illa billah", "bn": "লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ"}', '{"en": "There is no might nor power except with Allah", "bn": "আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই"}', 33, '{"en": "A treasure from the treasures of Paradise.", "bn": "জান্নাতের ধনভাণ্ডারগুলোর একটি।"}', 'Sahih al-Bukhari 6384; Sahih Muslim 2704', 'in_review', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dhikr_presets (id, arabic, transliteration, translation, default_target, virtue, source_ref, review_status, sort_order) VALUES ('a76fabb6-490d-5f6d-bcae-e6d6754f5466', 'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ', '{"en": "Allahumma salli ‘ala Muhammad", "bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদ"}', '{"en": "O Allah, send blessings upon Muhammad", "bn": "হে আল্লাহ, মুহাম্মাদের ওপর রহমত বর্ষণ করুন"}', 10, '{"en": "Whoever sends one blessing upon the Prophet ﷺ, Allah sends ten upon him.", "bn": "যে নবী ﷺ-এর ওপর একবার দরুদ পড়ে, আল্লাহ তার ওপর দশবার রহমত বর্ষণ করেন।"}', 'Sahih Muslim 408', 'in_review', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_dhikr_presets (id, arabic, transliteration, translation, default_target, virtue, source_ref, review_status, sort_order) VALUES ('70d39c70-4ca8-5e2c-b85e-8a416e875852', 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', '{"en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ‘ala kulli shay’in qadir", "bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু ওয়া হুওয়া আলা কুল্লি শাইয়িন কাদির"}', '{"en": "There is no god but Allah alone, without partner; His is the dominion and the praise, and He has power over all things", "bn": "আল্লাহ ছাড়া কোনো উপাস্য নেই, তিনি এক, শরিকহীন; রাজত্ব ও প্রশংসা তাঁরই, তিনি সবকিছুর ওপর ক্ষমতাবান"}', 100, '{"en": "A hundred times a day equals freeing ten slaves; a hundred good deeds are written and a hundred sins erased, and it is a protection from Shaytan that day.", "bn": "দিনে একশবার বললে দশজন দাস মুক্ত করার সওয়াব, একশ নেকি লেখা হয়, একশ গুনাহ মোছা হয় এবং সেদিন শয়তান থেকে সুরক্ষা।"}', 'Sahih al-Bukhari 3293; Sahih Muslim 2691', 'in_review', 10) ON CONFLICT (id) DO NOTHING;
