INSERT INTO is_announcements (id, title, body, placement, priority) VALUES ('4611b379-9b5b-5369-8531-efd7dba4a877', '{"en": "Welcome to the new Islamic Studio", "bn": "নতুন ইসলামিক স্টুডিওতে স্বাগতম", "ar": "مرحبًا بكم في استوديو إسلامي الجديد"}', '{"en": "Prayer times with reminders, Qibla, tasbih, duas, the Hijri calendar and the full Quran, now working offline. More features are on the way, in sha Allah.", "bn": "রিমাইন্ডারসহ নামাজের সময়, কিবলা, তাসবিহ, দোয়া, হিজরি ক্যালেন্ডার ও পূর্ণ কুরআন, এখন অফলাইনেও। ইনশাআল্লাহ আরও ফিচার আসছে।"}', 'home', 10) ON CONFLICT (id) DO NOTHING;
